% A homogeneous matrix polynomial on the unit simplex.
% Requires ROLMIP and YALMIP on the MATLAB path.
A1 = [1 0; 0 2];
A2 = [2 1; 1 3];
A3 = [3 0; 0 1];

% A(alpha) = alpha(1)*A1 + alpha(2)*A2 + alpha(3)*A3
% alpha(i) >= 0, sum(alpha) = 1.
A = rolmipvar([A1 A2 A3], 'A', 3, 1);

% Retrieve the coefficient of alpha(2).
coefficient = A([0 1 0]);
disp(coefficient{1});

% Matrix polynomial algebra on a two-vertex simplex.
% Requires ROLMIP and YALMIP on the MATLAB path.
A = rolmipvar({[1 0; 0 2], [2 1; 1 3]}, 'A', 2, 1);
B = rolmipvar({[0 1; 1 0], [1 0; 0 -1]}, 'B', 2, 1);

% Matrix multiplication preserves the order of the factors.
C = A*B;
S = A + B;

% Coefficient of alpha(1)*alpha(2) in the degree-two product.
coefficient = C([1 1]);
disp(coefficient{1});

% A common quadratic Lyapunov certificate for dx/dt = A(alpha)*x.
% Requires ROLMIP, YALMIP and SeDuMi on the MATLAB path.
yalmip('clear');
A1 = [-1 0.2; 0 -2];
A2 = [-2 0; 0.3 -1];
A = rolmipvar({A1, A2}, 'A', 2, 1);
P = rolmipvar(2, 2, 'P', 0, 0);
I = rolmipvar(eye(2), 'I');

% Uniform margins for this degree-one, two-vertex example.
F = [P >= I, A'*P + P*A <= -I];
options = sdpsettings('solver', 'sedumi', 'verbose', 0);
result = optimize(F, [], options);
assert(result.problem == 0, result.info);
disp(double(P));

