B = rolmipvar(B0, 'B');
C = rolmipvar(C0, 'C');

eta = sdpvar(1); % Squared H-infinity bound: eta = gamma^2.
P = rolmipvar(2,2,'P','sym',2,1); % P(a)=a_1*P_1+a_2*P_2
E = rolmipvar(eta, 'eta');
I2 = rolmipvar(eye(2), 'I2');

% Bounded-real LMI, affine in alpha and the decision variables.
